"""Build an offline human grading form from actual synthetic AI outputs."""
import argparse
import html
import json
from pathlib import Path
from claim_review import review_packet

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--directory',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args()
    packet=review_packet(args.directory)
    page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CaseFlow claim review</title>
<style>body{font:17px/1.5 system-ui;max-width:1050px;margin:2rem auto;padding:0 1rem;background:#f6f8fa;color:#203346}section{background:white;border:1px solid #c4cfd9;border-radius:10px;margin:1rem 0;padding:1rem}pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere}button,input,select,textarea{font:inherit;padding:.5rem;max-width:100%}button{cursor:pointer;margin:.3rem}label{display:block;margin:.5rem 0}textarea{box-sizing:border-box;width:100%;min-height:5rem}fieldset{margin:1rem 0;border:1px solid #a6b4c2}button:disabled{opacity:.5}#progress{font-weight:bold}.muted{color:#516272}</style>
<h1>Check what the AI claimed</h1>
<p>Read each output alongside the saved purchase and policy passages. Split a sentence containing multiple factual claims into separate entries. Mark a claim supported only when the cited passage or supplied purchase facts support the whole claim. A matching quotation alone is not enough.</p>
<p class="muted">This page sends nothing to a server. Every grade starts unchecked. Save a progress file before closing. These are synthetic development outputs unless the saved run says otherwise.</p>
<section><label>Your name or reviewer identifier <input id="reviewer" autocomplete="off"></label><button id="save">Download claim review / progress</button><label>Resume saved progress <input id="import" type="file" accept="application/json"></label><p id="progress" role="status"></p><p id="message" role="alert"></p></section>
<section><label>Output <select id="choice"></select></label><button id="previous">Previous</button><button id="next">Next</button><h2 id="title"></h2><h3>AI output</h3><pre id="claim"></pre><h3>Saved purchase</h3><pre id="purchase"></pre><h3>Citations in this output</h3><pre id="citations"></pre><h3>Policy passages available to this review</h3><pre id="evidence"></pre></section>
<section><h2>Your assessment</h2><div id="segments"></div><button id="add">Add another claim</button><label><input id="covered" type="checkbox"> All factual claims in this output are represented and graded above</label></section>
<pre id="data" hidden>DATA</pre>
<script>
const packet=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),grades={};let index=0;
for(const c of packet.claims){const option=document.createElement('option');option.value=c.key;option.textContent=c.key;$('choice').append(option);}
function grade(){const c=packet.claims[index];return grades[c.key]??= {textSha256:c.textSha256,coverageConfirmed:false,segments:[{text:c.text,verdict:'',rationale:''}]};}
function complete(g){return g?.coverageConfirmed===true&&g.segments?.length>0&&g.segments.every(s=>s.text.trim()&&s.rationale.trim()&&['SUPPORTED','UNSUPPORTED','NOT_A_FACT'].includes(s.verdict));}
function progress(){$('progress').textContent=packet.claims.filter(c=>complete(grades[c.key])).length+' / '+packet.claims.length+' outputs fully reviewed · '+packet.split+' run';}
function render(){if(!packet.claims.length){$('message').textContent='This run contains no completed review output.';return;}const c=packet.claims[index],g=grade();$('choice').value=c.key;$('title').textContent=c.key;$('claim').textContent=c.text;$('purchase').textContent=JSON.stringify(c.purchase,null,2);$('citations').textContent=c.citations.length?JSON.stringify(c.citations,null,2):'No citations on this output.';$('evidence').textContent=Object.entries(c.evidence).map(([id,e])=>id+'\n'+JSON.stringify(e,null,2)).join('\n\n')||'No policy passages supplied.';$('covered').checked=g.coverageConfirmed;$('previous').disabled=index===0;$('next').disabled=index===packet.claims.length-1;$('segments').replaceChildren();g.segments.forEach((s,i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent='Claim '+(i+1);box.append(legend);for(const [key,labelText] of [['text','One factual claim (or non-factual text)'],['verdict','Assessment'],['rationale','Reason, including the supporting or contradicting passage']]){const label=document.createElement('label');label.textContent=labelText;let input;if(key==='verdict'){input=document.createElement('select');for(const [value,text] of [['','Choose a grade'],['SUPPORTED','Supported'],['UNSUPPORTED','Unsupported'],['NOT_A_FACT','Not a factual assertion']]){const option=document.createElement('option');option.value=value;option.textContent=text;input.append(option);}}else input=document.createElement('textarea');input.value=s[key];input.oninput=()=>{s[key]=input.value;g.coverageConfirmed=false;$('covered').checked=false;progress();};label.append(input);box.append(label);}const remove=document.createElement('button');remove.textContent='Remove claim '+(i+1);remove.disabled=g.segments.length===1;remove.onclick=()=>{g.segments.splice(i,1);g.coverageConfirmed=false;render();};box.append(remove);$('segments').append(box);});progress();}
$('choice').onchange=()=>{index=packet.claims.findIndex(c=>c.key===$('choice').value);render();};$('previous').onclick=()=>{index--;render();};$('next').onclick=()=>{index++;render();};$('add').onclick=()=>{grade().segments.push({text:'',verdict:'',rationale:''});grade().coverageConfirmed=false;render();};$('covered').onchange=()=>{grade().coverageConfirmed=$('covered').checked;progress();};
$('save').onclick=()=>{const reviewer=$('reviewer').value.trim();if(!reviewer){$('message').textContent='Enter the actual reviewer identifier before saving.';return;}const report={method:packet.method,datasetVersion:packet.datasetVersion,datasetSha256:packet.datasetSha256,predictionsSha256:packet.predictionsSha256,reviewer,reviewedAt:new Date().toISOString(),grades,status:packet.claims.every(c=>complete(grades[c.key]))?'complete':'incomplete'};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='caseflow-claim-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('message').textContent='Saved '+report.status+' review. No quality gate is automatically passed.';};
$('import').onchange=async()=>{try{const r=JSON.parse(await $('import').files[0].text());if(['method','datasetVersion','datasetSha256','predictionsSha256'].some(k=>r[k]!==packet[k]))throw Error('This file belongs to another run.');const known=new Map(packet.claims.map(c=>[c.key,c]));if(!r.grades||typeof r.grades!=='object')throw Error('Invalid saved grades.');for(const [key,g] of Object.entries(r.grades)){if(!known.has(key)||g.textSha256!==known.get(key).textSha256||typeof g.coverageConfirmed!=='boolean'||!Array.isArray(g.segments)||!g.segments.length||g.segments.some(s=>typeof s.text!=='string'||typeof s.rationale!=='string'||!['','SUPPORTED','UNSUPPORTED','NOT_A_FACT'].includes(s.verdict)))throw Error('Invalid saved grade.');}Object.keys(grades).forEach(k=>delete grades[k]);Object.assign(grades,r.grades);$('reviewer').value=r.reviewer??'';render();$('message').textContent='Progress restored.';}catch(e){$('message').textContent=e.message;}};render();
</script></html>'''
    page=page.replace('>DATA</pre>','>'+html.escape(json.dumps(packet,ensure_ascii=True),quote=False)+'</pre>')
    args.output.parent.mkdir(parents=True,exist_ok=True)
    with args.output.open('x',encoding='utf-8') as output:output.write(page)
    print(f'Created {len(packet["claims"])} ungraded output sections; no human judgments invented.')
